'use strict';
/* Optional calendar feedback observes the action bus; it never blocks play. */
const travelOverlay=document.createElement('section');travelOverlay.id='timeTransition';travelOverlay.className='time-transition-strip';travelOverlay.hidden=true;travelOverlay.setAttribute('aria-label','Kalenderen går fremover');document.body.append(travelOverlay);
let timeFrame=0,timeTimer=0;
const calendarDate=d=>new Date(Date.UTC(2026,0,1+d)).toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
function closeTime(){cancelAnimationFrame(timeFrame);clearTimeout(timeTimer);travelOverlay.hidden=true;}
function showTime(from,to,type,origin){closeTime();if(to<=from||window.VestkystMoneyUI||localStorage.getItem('vestkyst-animations')==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const days=to-from;travelOverlay.innerHTML=`<div><span class="section-kicker">${days} ${days===1?'DAG GIKK':'DAGER GIKK'}</span><strong>${calendarDate(from)} → ${calendarDate(to)}</strong><div class="meter"><i id="countingBar" style="width:0%"></i></div></div><button class="text-button" id="skipCalendar">Hopp over</button>`;travelOverlay.hidden=false;$('#skipCalendar').onclick=closeTime;const start=performance.now(),duration=650;function frame(now){const t=Math.min(1,(now-start)/duration),bar=travelOverlay.querySelector('#countingBar');if(bar)bar.style.width=t*100+'%';if(t<1)timeFrame=requestAnimationFrame(frame);}timeFrame=requestAnimationFrame(frame);timeTimer=setTimeout(closeTime,3000);}
if(typeof G.on==='function')G.on('afterAction',(state,ctx)=>{showTime(ctx.before?.day??state.day,state.day,ctx.type,ctx.arg?.origin??state.trip?.origin);});
const priorTimeSettings=$('#settings').onclick;$('#settings').onclick=()=>{priorTimeSettings();$('#dialogBody').insertAdjacentHTML('beforeend',`<hr><label class="check-label"><input id="timeAnimationToggle" type="checkbox" ${localStorage.getItem('vestkyst-animations')!=='off'?'checked':''}> Bevegelse i oppgjør og reisekalender</label><p class="small">Slå av for å vise beløp og datoer med én gang. Spillet venter aldri på visningen.</p>`);$('#timeAnimationToggle').onchange=e=>{localStorage.setItem('vestkyst-animations',e.target.checked?'on':'off');if(!e.target.checked){closeTime();window.VestkystMoneyUI?.finishMotion?.();}};};
